episode.remediation_sql:
SELECT CASE WHEN denom = 0 THEN NULL ELSE (num * 100.0) / denom END AS percentage
FROM (
  SELECT
    SUM(CASE WHEN p.SEX = 'F' AND EXISTS (
      SELECT 1 FROM Laboratory l WHERE l.ID = p.ID AND l.PT >= 14
    ) THEN 1 ELSE 0 END) AS num,
    COUNT(*) AS denom
  FROM Patient p
  WHERE (CAST(strftime('%Y','now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER)) > 55
) AS t;
